INSERT INTO changelog (title, body, created_at) VALUES ('Meta: період — сьогодні / 7 / 30 днів / рік', 'Клієнт → Meta Ads → Огляд: перемикач періоду. Сьогодні (проти вчора), 7 днів (проти попередніх 7), 30 днів (проти попередніх 30), Рік (по місяцях). Цифри, рядок під ними і графік підлаштовуються. Порівняння 30 днів зʼявиться, коли система назбирає 60 днів даних. Також: у згорнутій лівій панелі клієнта «Записати зустріч» — тепер іконка мікрофона; кольори в «Бренді» більше не темніють при наведенні.', datetime('now'));
